// Flow:
//  1. Prompt 1: agent creates files, commits via hooks → checkpoint trailer ✓
//  2. Mid-turn: third-party tool (husky/lefthook) overwrites git hooks
//  3. Agent commits again (no hooks fire) → NO trailer
//  4. Prompt 2 starts (user-prompt-submit) → EnsureSetup reinstalls hooks
//  5. Agent commits via hooks → checkpoint trailer ✓ (hooks restored)
//
// The key insight: GitCommitWithShadowHooks invokes the binary directly (simulating
// working hooks), while GitAdd+GitCommit uses go-git without hooks (simulating
// overwritten hooks where `entire` is never called).
func TestHookOverwrite_MidTurnWipe_NextPromptRecovers(t *testing.T) {
	t.Parallel()

	env := NewFeatureBranchEnv(t)
	hooksDir := filepath.Join(env.RepoDir, ".git", "hooks")

	sess := env.NewSession()

	// === Prompt 1: normal flow, hooks work ===
	err := env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(
		sess.ID, "Create files A and B", sess.TranscriptPath)
	require.NoError(t, err)

	env.WriteFile("fileA.go", "package main\n\nfunc A() {}\n")
	env.WriteFile("fileB.go", "package main\n\nfunc B() {}\n")

	sess.CreateTranscript("Create files A and B", []FileChange{
		{Path: "fileA.go", Content: "package main\n\nfunc A() {}\n"},
		{Path: "fileB.go", Content: "package main\n\nfunc B() {}\n"},
	})

	// First commit — hooks are intact, binary is invoked → trailer added
	env.GitCommitWithShadowHooks("Add file A", "fileA.go")
	cpID1 := env.GetCheckpointIDFromCommitMessage(env.GetHeadHash())
	require.NotEmpty(t, cpID1, "first commit should have checkpoint trailer")

	// === Simulate husky/lefthook overwriting hooks mid-turn ===
	// This is what happens when an agent runs `npm install` and husky's
	// `prepare` lifecycle script reinstalls its own hooks.
	for _, hookName := range strategy.ManagedGitHookNames() {
		hookPath := filepath.Join(hooksDir, hookName)
		huskyContent := "#!/bin/sh\n# husky - do not edit\n. \"$(dirname \"$0\")/_/husky.sh\"\n"
		err := os.WriteFile(hookPath, []byte(huskyContent), 0o755)
		require.NoError(t, err)
	}

	// Verify hooks are overwritten
	require.False(t, strategy.IsGitHookInstalledInDir(t.Context(), env.RepoDir),
		"hooks should be detected as overwritten")

	// Second commit — hooks are gone, use plain go-git commit (no binary invoked).
	// This simulates the real-world situation after husky/lefthook has overwritten
	// our hooks: a commit is made where git would run a third-party hook that does
	// not call `entire`, so from Entire's perspective no hooks run and no trailer
	// is added.
	env.GitAdd("fileB.go")
	env.GitCommit("Add file B")
	cpID2 := env.GetCheckpointIDFromCommitMessage(env.GetHeadHash())
	assert.Empty(t, cpID2,
		"second commit should NOT have trailer (hooks were overwritten, entire never called)")

	// End prompt 1
	err = env.SimulateStop(sess.ID, sess.TranscriptPath)
	require.NoError(t, err)

	// === Prompt 2: EnsureSetup should reinstall hooks ===
	// NOTE: We use a new session here rather than reusing sess because the test
	// focuses on hook reinstallation, not same-session content detection. Using the
	// same session after stop+restart triggers a content detection edge case where
	// prepare-commit-msg doesn't see new content (separate issue from hook recovery).
	sess2 := env.NewSession()

	env.WriteFile("fileC.go", "package main\n\nfunc C() {}\n")

	sess2.CreateTranscript("Create file C", []FileChange{
		{Path: "fileC.go", Content: "package main\n\nfunc C() {}\n"},
	})

	err = env.SimulateUserPromptSubmitWithPromptAndTranscriptPath(
		sess2.ID, "Create file C", sess2.TranscriptPath)
	require.NoError(t, err)

	// Verify hooks were reinstalled by EnsureSetup
	require.True(t, strategy.IsGitHookInstalledInDir(t.Context(), env.RepoDir),
		"hooks should be reinstalled by EnsureSetup at prompt 2 start")

	// Verify overwritten hooks were backed up (chaining preserved)
	for _, hookName := range strategy.ManagedGitHookNames() {
		backupPath := filepath.Join(hooksDir, hookName+".pre-entire")
		_, err := os.Stat(backupPath)
		assert.NoError(t, err, "backup %s.pre-entire should exist after reinstall", hookName)
	}

	// Third commit — hooks restored, binary invoked again → trailer added
	env.GitCommitWithShadowHooks("Add file C", "fileC.go")
	cpID3 := env.GetCheckpointIDFromCommitMessage(env.GetHeadHash())
	assert.NotEmpty(t, cpID3,
		"third commit should have trailer (hooks reinstalled by prompt 2)")

	// Checkpoint IDs should be distinct
	if cpID3 != "" {
		assert.NotEqual(t, cpID1, cpID3,
			"checkpoint IDs from prompt 1 and prompt 2 should be distinct")
	}
}

	// Look for transcript file — use blob size for fast growth check when possible.
	// This avoids reading the full transcript content (potentially tens of MB) just
	// to count lines, which was the main source of PostCommit latency with many sessions.
	metadataDir := paths.EntireMetadataDir + "/" + state.SessionID
	var hasTranscriptFile bool
	var transcriptBlobSize int64

	if size, sizeErr := tree.Size(metadataDir + "/" + paths.TranscriptFileName); sizeErr == nil {
		hasTranscriptFile = true
		transcriptBlobSize = size
	} else if size, sizeErr := tree.Size(metadataDir + "/" + paths.TranscriptFileNameLegacy); sizeErr == nil {
		hasTranscriptFile = true
		transcriptBlobSize = size
	}

	// If shadow branch exists but has no transcript (e.g., carry-forward from mid-session commit),
	// check if the session has FilesTouched. Carry-forward sets FilesTouched with remaining files.
	if !hasTranscriptFile {
		if len(state.FilesTouched) > 0 {
			// Shadow branch has files from carry-forward - check if staged files overlap
			// AND have matching content (content-aware check).
			if len(opts.stagedFiles) > 0 {
				// PrepareCommitMsg context: check staged files overlap with content
				result := stagedFilesOverlapWithContent(ctx, repo, tree, opts.stagedFiles, state.FilesTouched)
				logging.Debug(logCtx, "sessionHasNewContent: no transcript, carry-forward with staged files",
					slog.String("session_id", state.SessionID),
					slog.Int("files_touched", len(state.FilesTouched)),
					slog.Int("staged_files", len(opts.stagedFiles)),
					slog.Bool("result", result),
				)
				return result, nil
			}
			// PostCommit context: no staged files, but we have carry-forward files.
			// Return true and let the caller do the overlap check with committed files.
			logging.Debug(logCtx, "sessionHasNewContent: no transcript, carry-forward without staged files (post-commit context)",
				slog.String("session_id", state.SessionID),
				slog.Int("files_touched", len(state.FilesTouched)),
			)
			return true, nil
		}
		// No transcript and no FilesTouched - fall back to live transcript check
		logging.Debug(logCtx, "sessionHasNewContent: no transcript and no files touched, checking live transcript",
			slog.String("session_id", state.SessionID),
		)
		return s.sessionHasNewContentFromLiveTranscript(ctx, state, opts.stagedFiles)
	}

	// Check if there's new content to condense. Two cases:
	// 1. Transcript has grown since last condensation (new prompts/responses)
	// 2. FilesTouched has files not yet committed (carry-forward scenario)
	//
	// For PrepareCommitMsg context, we verify staged files overlap with session's files
	// using content-aware matching to detect reverted files.
	// For PostCommit context, stagedFiles is nil/empty (files already committed),
	// so we return true and let the caller do the overlap check via filesOverlapWithContent.

	// Fast path: compare blob size against stored size from last condensation.
	// This avoids reading the full transcript content just to count items.
	var hasTranscriptGrowth bool
	switch {
	case state.CheckpointTranscriptSize > 0:
		hasTranscriptGrowth = transcriptBlobSize > state.CheckpointTranscriptSize
	case state.CheckpointTranscriptStart > 0:
		// Legacy session: condensed at least once (has line count) but no size tracking.
		// Cannot safely compare sizes — conservatively assume growth so condensation
		// can do the full content check. After one condensation with the new CLI,
		// CheckpointTranscriptSize will be populated and this path won't be hit again.
		hasTranscriptGrowth = true
	default:
		// Never condensed (CheckpointTranscriptStart == 0): any content means growth.
		hasTranscriptGrowth = transcriptBlobSize > 0
	}
	hasUncommittedFiles := len(state.FilesTouched) > 0

	logging.Debug(logCtx, "sessionHasNewContent: transcript size check",
		slog.String("session_id", state.SessionID),
		slog.Int64("transcript_blob_size", transcriptBlobSize),
		slog.Int64("checkpoint_transcript_size", state.CheckpointTranscriptSize),
		slog.Bool("has_transcript_growth", hasTranscriptGrowth),
		slog.Bool("has_uncommitted_files", hasUncommittedFiles),
	)

	if !hasTranscriptGrowth && !hasUncommittedFiles {
		return false, nil // No new content and no carry-forward files
	}

	// Check if staged files overlap with session's files with content-aware matching.
	// This is primarily for PrepareCommitMsg; in PostCommit, stagedFiles is nil/empty.
	if len(opts.stagedFiles) > 0 {
		result := stagedFilesOverlapWithContent(ctx, repo, tree, opts.stagedFiles, state.FilesTouched)
		logging.Debug(logCtx, "sessionHasNewContent: staged files overlap check",
			slog.String("session_id", state.SessionID),
			slog.Int("staged_files", len(opts.stagedFiles)),
			slog.Bool("result", result),
		)
		return result, nil
	}

	// No staged files - either PostCommit context or edge case.
	// Return transcript growth status. For PostCommit with hasTranscriptFile=true,
	// if there's no transcript growth, the session hasn't done new work since last checkpoint.
	// (Carry-forward creates a shadow branch WITHOUT transcript, handled in the block above.)
	logging.Debug(logCtx, "sessionHasNewContent: no staged files, returning transcript growth",
		slog.String("session_id", state.SessionID),
		slog.Bool("has_transcript_growth", hasTranscriptGrowth),
		slog.Bool("has_uncommitted_files", hasUncommittedFiles),
	)
	return hasTranscriptGrowth, nil
}

